// Component側
interface TextInputProps {
  defaultValue?: string;
}

export const TitleInput: React.FC<TextInputProps> = ({ defaultValue }) => {
  const { register } = useFormContext();
  return (
    <TextField
      {...register("title")}
      id="standard-basic"
      label="What is the Task's name..."
      variant="standard"
      defaultValue={defaultValue || ''}
    />
  );
}
```

1) switch APIs configuration to server-side;
2) add ROOT_APP to .env; 
3) update the 'dev' and 'start' scripts to run the project on new port 3333;

### 💬 Description
In ACF v6+ they decided to [drop Block ID](https://www.advancedcustomfields.com/resources/whats-new-with-acf-blocks-in-acf-6/).

This breaking changes break the behavior of this plugin, and Query like:

```
query NewQuery {
  post(id: "XXX") {
    translation(language: FR) {
      blocks {
        ... on AcfQuoteAvatarBlock {
          blockQuoteAvatarFields {
            quote
            fieldGroupName
            authorTitle
            author
          }
        }
      }
    }
  }
}
```

Started to return `null` values for acf fields:

```json
{
  "data": {
    "post": {
      "translation": {
        "blocks": [
          {},
          {
            "blockQuoteAvatarFields": {
              "quote": null,
              "fieldGroupName": "blockQuoteAvatarFields",
              "authorTitle": null,
              "author": null
            }
          },
          {},
          {},
          {},
          {
            "blockQuoteAvatarFields": {
              "quote": null,
              "fieldGroupName": "blockQuoteAvatarFields",
              "authorTitle": null,
              "author": null
            }
          },
        ]
      }
    }
  },
```

This "patch" (we can't say it "fix") the problem by generating an ID and attach acf metadata to it. Still unsure if it works with InnerBlocks content...
